//! Replay of the original `FSceneNode::ComputeRenderSize` against `fixtures/camera_render_size.txt`,
//! generated by `Build/camera_fixture_harness/gen_camera.sh` from `UnCamera.cpp` at 69c3263.
//! Every output float is compared bit-for-bit.
//!
//! Families: `render_size` (ortho, `RendMap` 13..=15) and `render_size_persp` (non-ortho). The
//! persp family reaches `UViewport::GetOuterUClient()->MaintainVerticalFOV` and
//! `UClient::GetEffectiveFovAngle`; its oracle is the pre-port body (`42a1e81^`, UnCamMgr.cpp:37-45)
//! compiled into the harness, so `viewport_maintain_vertical_fov` is the only extra service.

use std::collections::HashMap;
use std::ffi::c_void;
use std::mem::size_of;
use std::sync::atomic::{AtomicI32, AtomicUsize, Ordering};

use hp2_abi::engine::generated::{APlayerPawn, FSceneNode, UViewport};
use hp2_abi::{FCoords, FVector};
use hp2_engine::camera::{CameraServices, compute_render_size};

const FIXTURE: &str = include_str!("fixtures/camera_render_size.txt");
const ORTHO_CASES: usize = 48;
const PERSP_CASES: usize = 64;
const OUT_WORDS: usize = 46;

static SET_SCENE_CALLS: AtomicUsize = AtomicUsize::new(0);
static LAST_RENDER_DEV: AtomicUsize = AtomicUsize::new(0);
static LAST_FRAME: AtomicUsize = AtomicUsize::new(0);
/// `UClient::MaintainVerticalFOV` for the case being replayed.
static MAINTAIN: AtomicI32 = AtomicI32::new(0);

/// `URenderDevice::SetSceneNode(Frame)`: the only services entry the ortho branch reaches.
unsafe extern "C" fn record_set_scene(render_dev: *mut c_void, frame: *mut c_void) {
    SET_SCENE_CALLS.fetch_add(1, Ordering::SeqCst);
    LAST_RENDER_DEV.store(render_dev as usize, Ordering::SeqCst);
    LAST_FRAME.store(frame as usize, Ordering::SeqCst);
}

/// `GetOuterUClient()->MaintainVerticalFOV`: the persp branch reads it; the ortho branch never does.
unsafe extern "C" fn record_maintain(_viewport: *mut c_void) -> i32 {
    MAINTAIN.load(Ordering::SeqCst)
}

/// Fail-fast filler for every other services entry; compute_render_size must never reach it.
unsafe extern "C" fn unexpected_service() {
    panic!("compute_render_size reached an unexpected CameraServices entry");
}

fn services() -> CameraServices {
    // Every field of `CameraServices` is a function pointer (`camera.rs:36-204`), so a table of
    // one address has the right size and valid values; only the two entries below are set.
    const WORDS: usize = size_of::<CameraServices>() / size_of::<usize>();
    let filler = unexpected_service as unsafe extern "C" fn() as usize;
    let table: [usize; WORDS] = [filler; WORDS];
    let mut svc: CameraServices = unsafe { std::mem::transmute(table) };
    svc.render_dev_set_scene_node = record_set_scene;
    svc.viewport_maintain_vertical_fov = record_maintain;
    svc
}

struct Case {
    idx: usize,
    persp: bool,
    x: i32,
    y: i32,
    map: i32,
    maintain: i32,
    fov: f32,
    zoom: f32,
    coords: [f32; 12],
    uc: [f32; 12],
}

fn hex_f32(s: &str) -> f32 {
    f32::from_bits(u32::from_str_radix(s, 16).expect("hex float bits"))
}

fn hex_floats(s: &str) -> [f32; 12] {
    let v: Vec<f32> = s.split(',').map(hex_f32).collect();
    v.try_into().expect("12 floats")
}

fn parse_case(line: &str) -> Case {
    let mut it = line.split_whitespace();
    assert_eq!(it.next(), Some("case"));
    let family = it.next().expect("family");
    assert!(
        family == "render_size" || family == "render_size_persp",
        "unexpected family {family}"
    );
    let idx: usize = it.next().expect("idx").parse().expect("idx parses");
    let kv: HashMap<&str, &str> = it.map(|t| t.split_once('=').expect("key=value")).collect();
    Case {
        idx,
        persp: family == "render_size_persp",
        x: kv["x"].parse().expect("x"),
        y: kv["y"].parse().expect("y"),
        map: kv["map"].parse().expect("map"),
        maintain: kv
            .get("maintain")
            .map_or(0, |m| m.parse().expect("maintain")),
        fov: hex_f32(kv["fov"]),
        zoom: hex_f32(kv["zoom"]),
        coords: hex_floats(kv["coords"]),
        uc: hex_floats(kv["uc"]),
    }
}

fn fcoords(v: &[f32; 12]) -> FCoords {
    FCoords {
        origin: FVector {
            x: v[0],
            y: v[1],
            z: v[2],
        },
        x_axis: FVector {
            x: v[3],
            y: v[4],
            z: v[5],
        },
        y_axis: FVector {
            x: v[6],
            y: v[7],
            z: v[8],
        },
        z_axis: FVector {
            x: v[9],
            y: v[10],
            z: v[11],
        },
    }
}

/// Runs one case and returns the 46 output words in fixture order.
fn run_case(svc: &CameraServices, c: &Case) -> Vec<u32> {
    let mut actor: APlayerPawn = unsafe { std::mem::zeroed() };
    actor.rend_map = c.map;
    actor.base.fov_angle = c.fov;
    actor.base.ortho_zoom = c.zoom;
    let mut vp: UViewport = unsafe { std::mem::zeroed() };
    let mut render_dev = 0u8;
    vp.actor = (&mut actor as *mut APlayerPawn).cast();
    vp.ren_dev = (&mut render_dev as *mut u8).cast();
    let mut node: FSceneNode = unsafe { std::mem::zeroed() };
    node.viewport = (&mut vp as *mut UViewport).cast();
    node.x = c.x;
    node.y = c.y;
    node.coords = fcoords(&c.coords);
    node.uncoords = fcoords(&c.uc);

    MAINTAIN.store(c.maintain, Ordering::SeqCst);
    SET_SCENE_CALLS.store(0, Ordering::SeqCst);
    let frame: *mut FSceneNode = &mut node;
    unsafe { compute_render_size(svc, frame) };
    assert_eq!(SET_SCENE_CALLS.load(Ordering::SeqCst), 1, "case {}", c.idx);
    assert_eq!(
        LAST_RENDER_DEV.load(Ordering::SeqCst),
        vp.ren_dev as usize,
        "case {}",
        c.idx
    );
    assert_eq!(
        LAST_FRAME.load(Ordering::SeqCst),
        frame as usize,
        "case {}",
        c.idx
    );

    let n = &node;
    let mut out: Vec<f32> = Vec::with_capacity(OUT_WORDS);
    out.extend([
        n.fx,
        n.fy,
        n.fx2,
        n.fy2,
        n.fx15,
        n.fy15,
        n.effective_fov_angle,
    ]);
    out.extend([n.proj.x, n.proj.y, n.proj.z]);
    out.extend([n.r_proj.x, n.r_proj.y, n.r_proj.z]);
    out.extend([n.zoom, n.prj_xm, n.prj_xp, n.prj_ym, n.prj_yp]);
    out.extend(n.view_sides.iter().flat_map(|v| [v.x, v.y, v.z]));
    out.extend(n.view_planes.iter().flat_map(|p| [p.x, p.y, p.z, p.w]));
    assert_eq!(out.len(), OUT_WORDS);
    out.into_iter().map(f32::to_bits).collect()
}

#[test]
fn compute_render_size_matches_original() {
    let lines: Vec<&str> = FIXTURE.lines().collect();
    assert_eq!(lines.len(), (ORTHO_CASES + PERSP_CASES) * 3, "record count");
    let svc = services();
    let mut ortho = 0;
    let mut persp = 0;
    for rec in lines.chunks(3) {
        let c = parse_case(rec[0]);
        assert!(rec[1].starts_with("out "), "case {}: out line", c.idx);
        assert_eq!(rec[2], "setscene 1", "case {}: SetSceneNode count", c.idx);
        let want: Vec<u32> = rec[1]
            .split_whitespace()
            .skip(1)
            .map(|w| u32::from_str_radix(w, 16).expect("out word"))
            .collect();
        assert_eq!(want.len(), OUT_WORDS, "case {}: out width", c.idx);
        let got = run_case(&svc, &c);
        for (i, (g, w)) in got.iter().zip(&want).enumerate() {
            assert_eq!(
                g, w,
                "case {} word {} got {:08x} want {:08x}",
                c.idx, i, g, w
            );
        }
        if c.persp {
            persp += 1;
        } else {
            ortho += 1;
        }
    }
    assert_eq!(ortho, ORTHO_CASES, "ortho case count");
    assert_eq!(persp, PERSP_CASES, "persp case count");
}
